import{_ as a,o as t,c as s,ae as r}from"./chunks/framework.Dn6zxbF8.js";const m=JSON.parse('{"title":"Human-Readable IDs","description":"","frontmatter":{"id":"4860595695","title":"Human-Readable IDs","state":"Approved","created":"2024-03-24T00:00:00.000Z","category":"Platform","tags":["id"]},"headers":[],"relativePath":"adrs/4860595695/README.md","filePath":"adrs/4860595695/README.md"}'),n={name:"adrs/4860595695/README.md"};function i(o,e,l,d,u,h){return t(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="human-readable-ids" tabindex="-1">Human-Readable IDs <a class="header-anchor" href="#human-readable-ids" aria-label="Permalink to &quot;Human-Readable IDs&quot;">​</a></h1><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>Choosing the right type of IDs for APIs affects usability, security, and developer experience. Working with just UUIDs, integers, or random characters can be cumbersome and error-prone. These IDs are often hard to remember, debug, and integrate with other systems because they lack context about the resource type.</p><p>That difficulty is exacerbated for Business Analysts dealing with massive amounts of data from different sources, needing to understand the data structure and relationships between resources. Or for developers without much experience working with the system or domain.</p><p>Polymorphic values are a common pattern where you need to fetch a resource by its ID without knowing the resource&#39;s type. Some APIs use a hash map to store the type and ID, but this approach lacks human readability, requiring the type and ID to be printed together for usefulness.</p><p>In distributed systems, simplifying data understanding is critical. Whether using ETL software, data warehouses, or freelancers who don&#39;t have time to learn all the data combinations, it&#39;s important to keep data self-sufficient and easily understandable.</p><h3 id="positive-consequences" tabindex="-1">Positive Consequences <a class="header-anchor" href="#positive-consequences" aria-label="Permalink to &quot;Positive Consequences&quot;">​</a></h3><ul><li>Usability: Easier for humans to read, remember, and use.</li><li>Debugging: Simplifies identifying and understanding issues.</li><li>Integration: Eases integration with other systems by providing context.</li></ul><h3 id="negative-consequences" tabindex="-1">Negative Consequences <a class="header-anchor" href="#negative-consequences" aria-label="Permalink to &quot;Negative Consequences&quot;">​</a></h3><ul><li>Potential Length: Human-readable IDs might be longer.</li></ul><h2 id="resolution" tabindex="-1">Resolution <a class="header-anchor" href="#resolution" aria-label="Permalink to &quot;Resolution&quot;">​</a></h2><ul><li>You <strong>MUST</strong> use a human-readable ID as a single value to identify a resource.</li><li>You <strong>MUST</strong> include the resource type as a prefix in the ID.</li><li>You <strong>MUST</strong> <code>[resource type]_[resource id]</code> as the format for human-readable IDs.</li></ul><h2 id="links" tabindex="-1">Links <a class="header-anchor" href="#links" aria-label="Permalink to &quot;Links&quot;">​</a></h2><ul><li><a href="https://dev.to/stripe/designing-apis-for-humans-object-ids-3o5a" target="_blank" rel="noreferrer">Designing APIs for humans: Object IDs</a></li><li><a href="https://strawhatllc.notion.site/Data-Information-Knowledge-and-Wisdom-142b2220e11d8004a842fd982fde319c" target="_blank" rel="noreferrer">About Data vs. Information</a></li></ul>',14)])])}const f=a(n,[["render",i]]);export{m as __pageData,f as default};
